/** \brief  Icu_Isr_Vector_23_Cat1 
 **
 ** Category 1 interrupt service routine for vector 23 of channel GPIO_2.
 **
 */
ISR_NATIVE( Icu_Isr_Vector_23_Cat1 )
{
  /* Deviation from MISRA-C:2004 rule 3.1, 11.3, MISRA-C:2012 Rule-11.4
     Justification: The hardware address is provided as integral type by configuration. However, the hardware access must be handled by using pointer. */
  /* PRQA S 303 1 */
  Icu_Isr_Vector_Internal(ICU_BASE_ADDR_GPIO_2_1, ICU_HWRESOURCE_GPIO_2_1, 1U);
}

